import{_ as t,o,c as n,ao as i}from"./chunks/framework.cyfFUN0r.js";const f=JSON.parse('{"title":"Blocking and hiding profiles","description":"","frontmatter":{"prev":false,"next":false,"title":"Blocking and hiding profiles"},"headers":[],"relativePath":"guides/blocking-and-hiding-profiles.md","filePath":"guides/blocking-and-hiding-profiles.md"}'),r={name:"guides/blocking-and-hiding-profiles.md"};function s(a,e,l,d,h,p){return o(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="blocking-and-hiding-profiles" tabindex="-1">Blocking and hiding profiles <a class="header-anchor" href="#blocking-and-hiding-profiles" aria-label="Permalink to “Blocking and hiding profiles”">​</a></h1><h2 id="block" tabindex="-1">How to block users in Open Grind? <a class="header-anchor" href="#block" aria-label="Permalink to “How to block users in Open Grind?”">​</a></h2><ol><li>Open the profile</li><li>Tap the <strong>⋯</strong> menu</li><li>Tap <strong>Block profile</strong></li></ol><p>You can also tap <strong>Block profile</strong> right after you report someone.</p><p>To unblock, open the profile and tap <strong>Unblock</strong>, or turn it off in <strong>Settings → Account Settings → Blocked users</strong>.</p><h2 id="hide" tabindex="-1">How to hide users in Open Grind? <a class="header-anchor" href="#hide" aria-label="Permalink to “How to hide users in Open Grind?”">​</a></h2><ol><li>Open the profile</li><li>Tap the <strong>⋯</strong> menu</li><li>Tap <strong>Hide profile</strong></li></ol><p>To unhide, open the profile and tap <strong>Unhide</strong>, or turn it off in <strong>Settings → Account Settings → Hidden users</strong>.</p><h2 id="difference" tabindex="-1">What&#39;s the difference between blocking and hiding users in Grindr? <a class="header-anchor" href="#difference" aria-label="Permalink to “What&#39;s the difference between blocking and hiding users in Grindr?”">​</a></h2><p>They have different <strong>limits</strong>.</p><table tabindex="0"><thead><tr><th></th><th>Block profile</th><th>Hide profile</th></tr></thead><tbody><tr><td>Works on all profiles</td><td><strong><a href="#why-cant-i-block-some-profiles">No</a></strong></td><td>Yes</td></tr><tr><td>Reduces number of profiles you see</td><td>No</td><td><strong><a href="https://help.grindr.com/hc/en-us/articles/35697847464467-Hiding-profiles" target="_blank" rel="noreferrer">Yes</a></strong></td></tr><tr><td>List cap</td><td><strong>Capped</strong> at unknown number</td><td>No cap</td></tr><tr><td>Conversation</td><td>Cleared permanently</td><td>Comes back when unhidden</td></tr></tbody></table><p>Both make yours and theirs profile inaccessible and non-interactable for each other.</p><h2 id="why-cant-i-block-some-profiles" tabindex="-1">Why can&#39;t I block some Grindr profiles? <a class="header-anchor" href="#why-cant-i-block-some-profiles" aria-label="Permalink to “Why can&#39;t I block some Grindr profiles?”">​</a></h2><p>Grindr only lets you block people you&#39;ve interacted with, for example chatted with. On other profiles, the official Grindr app shows <strong>Hide</strong> instead of <strong>Block</strong>.</p><p>Open Grind shows <strong>Block</strong> on every profile. Grindr usually accepts these blocks, but sometimes it ignores them. After you block someone, Open Grind checks your blocked list. If the profile isn&#39;t there, the profile comes back and you&#39;ll see &quot;Blocking this profile failed&quot;.</p><p>When that happens, <a href="#hide">hide the profile</a> instead.</p>',16)])])}const g=t(r,[["render",s]]);export{f as __pageData,g as default};
